#pragma once
#include <string>
#include <vector>

// XUnity.AutoTranslator text file (BepInEx/Translation/<lang>/Text/_AutoGeneratedTranslations.txt):
// one "English=Translation" per line, '#' comments, "r:" lines are regular expressions,
// "\=" is an escaped '=' and "\n" a line break. Texts are kept in this escaped form.
struct AtEntry {
    std::string src, dst;
};

std::vector<AtEntry> parse_at(const std::string& text);
std::string dump_at(const std::vector<AtEntry>& entries);
// reference/hardcoded-en.txt: one English text per line, '#' comments
std::vector<std::string> parse_hardcoded(const std::string& text);
// escapes '=' that is not escaped yet
std::string at_escape(const std::string& s);
// minimal AutoTranslator config for a language code (offline, no online translator).
// collect: every text the plugin sees is written to Translation/<code>/FoundTexts.txt
std::string at_config(const std::string& code, bool collect = false);
// texts in the format of the AutoTranslator files: '=' and line breaks escaped
std::string at_key(const std::string& s);
